<script setup>
import { ref, watch } from 'vue';
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import HubNav from './HubNav.vue';
import './hub.css';
const props=defineProps({companies:Object,query:String,selected:Object,stats:Object});
const page=usePage();const q=ref(props.query);const form=useForm({version:1,holding:'',industry:'',verification:'Не проверено',target:false,inn:'',website:'',owner_raw:'',relationship:'',need:'',comment:''});
watch(()=>props.selected,s=>{if(s){for(const k of Object.keys(form.data()))form[k]=s[k]??'';form.target=!!s.target;}},{immediate:true});
const search=()=>router.get('/projects/sales-hub/companies',{q:q.value},{preserveState:true});
const save=()=>form.patch('/projects/sales-hub/companies/'+props.selected.id,{preserveScroll:true});
</script>
<template><Head title="Компании"/><AppLayout><div class="saleshub"><HubNav/><div class="page-head"><div><p class="eyebrow">СПРАВОЧНИК</p><h1>Компании</h1></div></div><form class="panel actions" @submit.prevent="search"><input v-model="q" placeholder="Компания или холдинг"><button class="primary">Найти</button></form><div class="result-head"><strong>{{companies.total}} компаний</strong><div class="actions"><Link v-if="companies.prev_page_url" :href="companies.prev_page_url">←</Link><span>{{companies.current_page}} / {{companies.last_page}}</span><Link v-if="companies.next_page_url" :href="companies.next_page_url">→</Link></div></div><div class="table-scroll"><table><thead><tr><th>Компания</th><th>Холдинг</th><th>Отрасль</th><th>ЛПР</th><th>Целевая</th><th>Проверка</th></tr></thead><tbody><tr v-for="c in companies.data" :key="c.id"><td><Link :href="'/projects/sales-hub/companies?id='+c.id+'&q='+encodeURIComponent(q)">{{c.name}}</Link></td><td>{{c.holding||'—'}}</td><td>{{c.industry||'—'}}</td><td><Link :href="'/projects/sales-hub?company_id='+c.id">{{c.contacts_count}}</Link></td><td>{{c.target?'Да':'Нет'}}</td><td>{{c.verification}}</td></tr></tbody></table></div><div v-if="selected" class="overlay"><section class="drawer" role="dialog" aria-modal="true" aria-label="Карточка компании"><div class="page-head"><h2>{{selected.name}}</h2><Link :href="'/projects/sales-hub/companies?q='+encodeURIComponent(q)">Закрыть</Link></div><div class="metrics"><div v-for="[label,v] in [['Контактов',stats.total],['Почта',stats.email],['Телефон',stats.phone],['Мессенджер',stats.messenger]]" :key="label" class="metric"><small>{{label}}</small><strong>{{v||0}}</strong></div></div><Link class="button primary" :href="'/projects/sales-hub?company_id='+selected.id">Показать контакты компании</Link><form @submit.prevent="save"><fieldset :disabled="page.props.auth.user.role!=='admin'||form.processing"><label v-for="[key,label] in [['holding','Холдинг'],['industry','Отрасль'],['inn','ИНН'],['website','Сайт'],['owner_raw','Ответственный'],['relationship','Статус сотрудничества'],['need','Потребность'],['comment','Комментарий']]" :key="key">{{label}}<input v-model="form[key]"></label><label>Проверка<select v-model="form.verification"><option v-for="v in ['Не проверено','На проверке','Подтверждено','Отклонено']" :key="v">{{v}}</option></select></label><label><input type="checkbox" v-model="form.target"> Целевая компания</label><button v-if="page.props.auth.user.role==='admin'" class="primary">Сохранить</button></fieldset><p v-for="e in form.errors" :key="e" class="error">{{e}}</p></form></section></div></div></AppLayout></template>
